def isi_jenis(apps, schema_editor):
    """Nota lama: beri jenis dan tandai yang melanggar aturan 12 Nov 2026 (dibatalkan lalu diinput ulang)."""
    Piutang = apps.get_model("master", "Piutang")
    for p in Piutang.objects.filter(batal=False):
        kurang = p.dibayar < p.total
        lama = False
        if p.status_barang == "ambil":
            jenis, lama = "titipan", kurang
        elif p.status_barang == "pesan":
            jenis = "invoice" if p.jenis_acc == "invoice" else "pesanan"
        elif p.status_barang == "antar":
            jenis = "cod" if kurang else ""
            lama = kurang and len("".join(c for c in (p.telepon or "") if c.isdigit())) < 8
        else:
            jenis = "invoice" if kurang else ""
            lama = kurang and p.jenis_acc != "invoice"
        Piutang.objects.filter(pk=p.pk).update(jenis=jenis, aturan_lama=lama)


